    function renderTimeline(tpData, dpData, operations, globalMaxTime) {
        // Convert data to Plotly format
        const tpTraces = createPlotlyTraces(tpData, operations, 'TP');
        const dpTraces = createPlotlyTraces(dpData, operations, 'DP');

        // Common layout configuration
        const layout = {
            xaxis: {
                title: 'Time (ms)',
                range: [0, globalMaxTime],
                showgrid: true,
                gridcolor: '#e0e0e0',
                zeroline: false
            },
            yaxis: {
                visible: false,
                range: [-1, 1],
                fixedrange: true
            },
            height: 200,
            margin: { l: 50, r: 50, t: 60, b: 50 },
            hovermode: 'closest',
            showlegend: false,
            legend: {
                x: 0.5,
                y: 1.25,
                xanchor: 'center',
                yanchor: 'bottom',
                orientation: 'h',
                bgcolor: 'rgba(255, 255, 255, 0.9)',
                bordercolor: '#e0e0e0',
                borderwidth: 1
            },
            plot_bgcolor: '#fafafa',
            paper_bgcolor: 'white'
        };

        const config = {
            responsive: true,
            displayModeBar: true,
            modeBarButtonsToRemove: ['lasso2d', 'select2d'],
            displaylogo: false
        };

        // Render both plots
        Plotly.newPlot('plot-tp', tpTraces, layout, config);
        Plotly.newPlot('plot-dp', dpTraces, layout, config);
    }

    function createPlotlyTraces(data, operations, parallelType) {
        // Group data by operation type (sync vs compute)
        const syncOps = [6, 14, 17]; // all-reduce (attention), all-reduce (mlp), all-gather
        const syncData = [];
        const computeData = [];

        data.forEach(d => {
            if (syncOps.includes(d.ops)) {
                syncData.push(d);
            } else {
                computeData.push(d);
            }
        });

        const traces = [];

        // Create trace for compute operations (grouped as one legend item)
        const computeXPoints = [];
        const computeYPoints = [];
        const computeText = [];

        computeData.forEach(d => {
            const op = operations.find(o => o.num === d.ops);
            if (!op) return;

            const numPoints = 20;
            for (let i = 0; i <= numPoints; i++) {
                const t = d.timestamp + (d.duration * i / numPoints);
                computeXPoints.push(t);
                computeYPoints.push(0);
                computeText.push(
                    `<b>Op ${d.ops}:</b> ${op.operation}<br>` +
                    `<b>Type:</b> Compute<br>` +
                    `<b>Block:</b> ${op.block}<br>` +
                    `<b>Time:</b> ${d.timestamp.toFixed(3)} ms<br>` +
                    `<b>Duration:</b> ${d.duration.toFixed(3)} ms<br>` +
                    `<b>Kernel:</b> ${d.kernelName.substring(0, 60)}...`
                );
            }
            // Add null to separate line segments
            computeXPoints.push(null);
            computeYPoints.push(null);
            computeText.push('');
        });

        if (computeXPoints.length > 0) {
            traces.push({
                x: computeXPoints,
                y: computeYPoints,
                mode: 'lines',
                line: {
                    width: 15,
                    color: '#616161'
                },
                fill: 'none',
                text: computeText,
                hovertemplate: '%{text}<extra></extra>',
                showlegend: parallelType === 'TP',  // Only show legend on TP plot
                name: 'Compute Operations',
                legendgroup: 'compute',
                hoverlabel: {
                    bgcolor: 'rgba(0, 0, 0, 0.9)',
                    font: { color: 'white', size: 12 },
                    bordercolor: '#616161'
                }
            });
        }

        // Create trace for sync operations (grouped as one legend item)
        const syncXPoints = [];
        const syncYPoints = [];
        const syncText = [];

        syncData.forEach(d => {
            const op = operations.find(o => o.num === d.ops);
            if (!op) return;

            const numPoints = 20;
            for (let i = 0; i <= numPoints; i++) {
                const t = d.timestamp + (d.duration * i / numPoints);
                syncXPoints.push(t);
                syncYPoints.push(0);
                syncText.push(
                    `<b>Op ${d.ops}:</b> ${op.operation}<br>` +
                    `<b>Type:</b> Sync (Communication)<br>` +
                    `<b>Block:</b> ${op.block}<br>` +
                    `<b>Time:</b> ${d.timestamp.toFixed(3)} ms<br>` +
                    `<b>Duration:</b> ${d.duration.toFixed(3)} ms<br>` +
                    `<b>Kernel:</b> ${d.kernelName.substring(0, 60)}...`
                );
            }
            // Add null to separate line segments
            syncXPoints.push(null);
            syncYPoints.push(null);
            syncText.push('');
        });

        if (syncXPoints.length > 0) {
            traces.push({
                x: syncXPoints,
                y: syncYPoints,
                mode: 'lines',
                line: {
                    width: 15,
                    color: '#d32f2f'
                },
                fill: 'none',
                text: syncText,
                hovertemplate: '%{text}<extra></extra>',
                showlegend: parallelType === 'TP',  // Only show legend on TP plot
                name: 'Sync Operations',
                legendgroup: 'sync',
                hoverlabel: {
                    bgcolor: 'rgba(0, 0, 0, 0.9)',
                    font: { color: 'white', size: 12 },
                    bordercolor: '#d32f2f'
                }
            });
        }

        return traces;
    }
